# List the session artifacts
import os

session_dir = "/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/seen-5/play/users/u032/system/state/session-artifacts/"
workspace = "/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/seen-5/play/users/u032/system/state/workspace"

if os.path.exists(session_dir):
    for item in os.listdir(session_dir):
        print(f"Item: {item}")
        path = f"{session_dir}/{item}"
        if os.path.isfile(path):
            print(f"  (file, size: {os.path.getsize(path)})")
else:
    print("Session dir doesn't exist")

# List workspace again
print("\nWorkspace contents:")
for item in sorted(os.listdir(workspace)):
    print(f"  {item}")

# Try to read the latest session log
session_dir = "/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/seen-5/play/users/u032/system/state/session-artifacts/"
latest_log = None

for item in sorted(os.listdir(session_dir)):
    path = os.path.join(session_dir, item)
    if os.path.isdir(path):
        log_file = os.path.join(path, item + '.jsonl')
        if os.path.exists(log_file):
            latest_log = log_file
            break

if latest_log:
    print(f"Reading log: {latest_log}")
    with open(latest_log) as f:
        lines = f.readlines()
    print(f"Total lines: {len(lines)}")

    # Show recent lines
    for line in lines[-10:]:
        print(line[:300])
else:
    print("No log found!")

